import org.junit.Test;

import java.lang.reflect.Method;

import static org.junit.Assert.assertEquals;

public class TableBuilderRefactorTest {

  @Test
  public void testTableBuilderFluentApiAndBuildSignature() throws Exception {
    // Ensure TableBuilder methods return TableBuilder for fluent API
    Class<?> builder = Class.forName("org.apache.hadoop.hbase.client.TableBuilder");

    String[] intSetterNames = {
        "setOperationTimeout",
        "setRpcTimeout",
        "setReadRpcTimeout",
        "setWriteRpcTimeout"
    };

    for (String name : intSetterNames) {
      Method m = builder.getMethod(name, int.class);
      assertEquals("Method '" + name + "' must return TableBuilder for fluent chaining",
          builder, m.getReturnType());
    }

    Method writeBuffer = builder.getMethod("setWriteBufferSize", long.class);
    assertEquals("setWriteBufferSize must return TableBuilder for fluent chaining",
        builder, writeBuffer.getReturnType());

    // Ensure build() returns a Table instance
    Method build = builder.getMethod("build");
    Class<?> table = Class.forName("org.apache.hadoop.hbase.client.Table");
    assertEquals("build() must return org.apache.hadoop.hbase.client.Table",
        table, build.getReturnType());
  }
}
